<div class="deliveries-workspace"><section class="admin-page-head"><div><p class="admin-kicker">INVENTARIO Y LOGÍSTICA</p><h1>Devoluciones</h1><p>Controla solicitudes, autorizaciones y movimientos físicos vinculados con entregas y recepciones.</p></div><?php if($canCreate):?><a class="admin-primary-button" data-admin-form-link href="/admin/returns/create">+ Registrar devolución</a><?php endif?></section>
<section class="deliveries-guide" aria-label="Proceso de devolución"><div><span>01</span><div><h2>Registra</h2><p>Selecciona el documento y cantidades realmente elegibles.</p></div></div><div><span>02</span><div><h2>Autoriza</h2><p>La aprobación no modifica existencias.</p></div></div><div><span>03</span><div><h2>Confirma el movimiento</h2><p>El inventario cambia una sola vez al confirmar la operación física.</p></div></div></section>
<section class="admin-panel deliveries-filters"><header><h2>Buscar devoluciones</h2><p>Filtra por folio, documento, contraparte, tipo, estado o fecha.</p></header><form class="returns-filter-grid" method="get" action="/admin/returns"><label class="admin-field returns-filter-wide"><span>Folio, documento o contraparte</span><input type="search" name="q" value="<?= e($q) ?>" maxlength="120"></label><label class="admin-field"><span>Tipo</span><select name="type"><option value="">Todos</option><?php foreach(Rules::TYPES as$key=>$label):?><option value="<?= e($key) ?>" <?= $type===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="">Todos</option><?php foreach(Rules::STATUSES as$key=>$label):?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label><label class="admin-field returns-filter-wide"><span>Sucursal</span><select name="branch_id"><option value="">Todas autorizadas</option><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field returns-filter-wide"><span>Desde</span><input type="date" name="from" value="<?= e($from??'') ?>"></label><label class="admin-field returns-filter-wide"><span>Hasta</span><input type="date" name="until" value="<?= e($until??'') ?>"></label><div class="returns-filter-actions"><button class="admin-secondary-button">Aplicar filtros</button><?php if($hasFilters):?><a class="deliveries-text-link" href="/admin/returns">Limpiar</a><?php endif?></div></form></section>
<section class="admin-panel admin-table-panel deliveries-directory"><header class="deliveries-directory-heading"><div><h2>Devoluciones registradas</h2><p>Seguimiento operativo sin efectos contables ni fiscales.</p></div><span><?= e(count($page->items)) ?> en esta página</span></header><?php if(!$page->items):?><div class="deliveries-empty"><h3><?= ($q!==''||$status!==''||$type!==''||$branchId||$from||$until)?'Sin coincidencias':'Aún no hay devoluciones registradas' ?></h3><p>Las devoluciones aparecerán aquí cuando se vinculen con una entrega o recepción existente.</p><?php if($canCreate):?><a class="admin-primary-button" data-admin-form-link href="/admin/returns/create">Registrar devolución</a><?php endif?></div><?php else:?><div class="admin-table-wrap" tabindex="0" role="region" aria-label="Devoluciones registradas"><table class="admin-table"><thead><tr><th>Folio / fecha</th><th>Tipo / documento</th><th>Cliente o proveedor</th><th>Sucursal</th><th>Estado</th><th>Partidas</th><th>Acciones</th></tr></thead><tbody><?php foreach($page->items as$row):?><tr><td data-label="Folio / fecha"><div><?= e($row['folio']) ?><small><?= e($row['created_at']) ?> UTC</small></div></td><td data-label="Tipo / documento"><div><?= e(Rules::TYPES[$row['return_type']]) ?><small><?= e($row['source_reference']) ?></small></div></td><td data-label="Cliente o proveedor"><?= e($row['counterparty_name']) ?></td><td data-label="Sucursal"><?= e($row['branch_name']) ?></td><td data-label="Estado"><span class="deliveries-status" data-state="<?= e($row['status']) ?>"><?= e(Rules::STATUSES[$row['status']]) ?></span></td><td data-label="Partidas"><?= e($row['item_count']) ?></td><td class="admin-actions"><a class="admin-secondary-button" data-admin-form-link href="/admin/returns/detail?id=<?= e($row['id']) ?>">Abrir</a></td></tr><?php endforeach?></tbody></table></div><?php endif?><?php if($page->offset||$page->hasMore):?><nav class="admin-pagination" aria-label="Paginación"><?php $params=['q'=>$q,'status'=>$status,'type'=>$type,'branch_id'=>$branchId,'from'=>$from,'until'=>$until];if($page->offset):?><a href="?<?= e(http_build_query($params+['offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="?<?= e(http_build_query($params+['offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav><?php endif?></section></div>
